// 提取 Mattermost Outgoing Webhook 的訊息內容
const body = $input.first().json.body;
const text = body.text || '';
const query = text.replace(/@ai-assistant/gi, '').trim();
const channelId = body.channel_id;
const userName = body.user_name || 'user';
const userId = body.user_id || 'unknown';
return [{json: {query: query || 'hello', channelId, userName, userId}}];

// 每人每日額度限制（使用 workflow static data 持久化）
const staticData = $getWorkflowStaticData('global');
const userId = $json.userId;
const today = new Date().toISOString().split('T')[0];
const DAILY_LIMIT = 50;

// 初始化 rate 資料結構
if (!staticData.rate) staticData.rate = {};
const key = userId;

// 日期變更時重置計數
if (!staticData.rate[key] || staticData.rate[key].date !== today) {
  staticData.rate[key] = { date: today, count: 0 };
}

const currentCount = staticData.rate[key].count;
const isAllowed = currentCount < DAILY_LIMIT;

if (isAllowed) {
  staticData.rate[key].count = currentCount + 1;
}

return [{json: {
  ...$json,
  rateAllowed: isAllowed,
  rateRemaining: Math.max(0, DAILY_LIMIT - currentCount - (isAllowed ? 1 : 0)),
  rateCount: currentCount + (isAllowed ? 1 : 0),
  dailyLimit: DAILY_LIMIT
}}];

// 簡單意圖路由：關鍵字分類
const query = $json.query.toLowerCase();

// 程式碼相關關鍵字（Phase 3 才開放）
const codeKeywords = ['review pr', 'write test', 'debug code', 'refactor', 'analyze bug', 'code review', '程式碼審查', '寫測試'];
// 資料查詢關鍵字（Phase 4 才開放）
const dataKeywords = ['query db', 'sql ', 'select from', '查資料庫', '跑報表', '資料庫查詢'];

let intent = 'general';

for (const kw of codeKeywords) {
  if (query.includes(kw)) { intent = 'code'; break; }
}
if (intent === 'general') {
  for (const kw of dataKeywords) {
    if (query.includes(kw)) { intent = 'data'; break; }
  }
}

return [{json: { ...$json, intent }}];

// 解析 Dify SSE 串流回應
const raw = $input.first().json.data || $input.first().json.body || '';
const text = typeof raw === 'string' ? raw : JSON.stringify(raw);

let answer = '';
const lines = text.split('\n');
for (const line of lines) {
  if (line.startsWith('data: ')) {
    try {
      const data = JSON.parse(line.substring(6));
      if (data.answer) {
        answer += data.answer;
      }
    } catch (e) {}
  }
}

if (!answer) {
  answer = '抱歉，無法處理您的請求。請稍後再試。';
}

const channelId = $('Extract Message').first().json.channelId;
const userId = $('Extract Message').first().json.userId;
const userName = $('Extract Message').first().json.userName;
const rateRemaining = $('Rate Limiter').first().json.rateRemaining;
const dailyLimit = $('Rate Limiter').first().json.dailyLimit;
return [{json: {answer, channelId, userId, userName, rateRemaining, dailyLimit}}];

// 記錄使用統計到 Static Data
const staticData = $getWorkflowStaticData('global');
const userId = $json.userId;
const userName = $json.userName;

if (!staticData.stats) {
  staticData.stats = { totalRequests: 0, users: {} };
}
staticData.stats.totalRequests++;

if (!staticData.stats.users[userId]) {
  staticData.stats.users[userId] = { name: userName, total: 0 };
}
staticData.stats.users[userId].total++;

// 透傳原始資料
return [$input.first()];

